use super::*;
use crate::standards::v1::subsets::value::schema::snapshot::{SemioValue,ValueId};
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->SemioGraphSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let first=GraphNodeId::new(f["nodeIds"][0].as_str().unwrap());let second=GraphNodeId::new(f["nodeIds"][1].as_str().unwrap());SemioGraphSnapshot{schema:f["schema"].as_str().unwrap().into(),nodes:vec![SemioGraphNode{id:first.clone(),kind:"typed".into(),label:f["text"].as_str().unwrap().into(),position:SemioPoint2{x:-2.5,y:3.25},ports:f["ports"].as_array().unwrap().iter().map(|p|SemioGraphPort{name:p[0].as_str().unwrap().into(),kind:match p[1].as_str().unwrap(){"in"=>SemioGraphPortKind::In,"out"=>SemioGraphPortKind::Out,_=>SemioGraphPortKind::InOut}}).collect(),properties:vec![SemioValueEntry{key:"same".into(),value:SemioValue::Map{entries:vec![SemioValueEntry{key:"nested".into(),value:SemioValue::List{items:vec![SemioValue::Str{value:"payload".into()},SemioValue::Ref{id:ValueId::new(f["externalValueId"].as_str().unwrap())}]}}]}},SemioValueEntry{key:"same".into(),value:SemioValue::Bytes{value:vec![0,255]}}]},SemioGraphNode{id:second.clone(),..SemioGraphNode::default()}],edges:vec![SemioGraphEdge{id:GraphEdgeId::new("forward"),source:first.clone(),target:second.clone(),kind:"data".into(),label:"one".into()},SemioGraphEdge{id:GraphEdgeId::new("backward"),source:second,target:first.clone(),kind:"data".into(),label:"two".into()},SemioGraphEdge{id:GraphEdgeId::new("self"),source:first.clone(),target:first,kind:"self".into(),label:"three".into()}]}}
fn project(value:&SemioGraphSnapshot)->SqliteDatabase{value.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(db:&SqliteDatabase)->Result<SemioGraphSnapshot,String>{SemioGraphSnapshot::from_sqlite_database(db,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]
fn sqlite_snapshot_semio_graph_typed_properties_ports_cycles_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioGraphSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioGraphSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioGraphSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioGraphSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));assert_eq!(restore(&project(&SemioGraphSnapshot::default())).unwrap(),SemioGraphSnapshot::default());}
#[test]
fn sqlite_snapshot_semio_graph_rejects_foreign_keys_ordinals_identity_and_budget_corruption(){let original=project(&fixture());for change in 0..5{let mut db=original.clone();match change{0=>db.table_mut("semio_graph_edge").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>db.table_mut("semio_graph_port").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>db.table_mut("semio_graph_node").unwrap().rows[1].values[3]=SqliteValue::Text("first".into()),3=>db.table_mut("semio_graph_property").unwrap().rows[0].values[4]=SqliteValue::Integer(999),_=>db.table_mut("semio_graph_port").unwrap().rows[0].values[4]=SqliteValue::Text("unknown".into())}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioGraphSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_graph_independent_join_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT kind FROM semio_graph_port ORDER BY ordinal').all().map(r=>r.kind).join(',')!=='in,out,in_out')throw Error('ports');if(db.query('SELECT source_node_id,target_node_id FROM semio_graph_edge WHERE native_id=\"self\"').get().source_node_id!==1)throw Error('self edge');db.query(\"UPDATE semio_graph_value SET string_value='independently edited' WHERE kind='str'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let SemioValue::Map{entries}=&mut expected.nodes[0].properties[0].value{if let SemioValue::List{items}=&mut entries[0].value{items[0]=SemioValue::Str{value:"independently edited".into()};}}assert_eq!(restored,expected);}

#[test]
fn sqlite_snapshot_semio_graph_bare_owner_capability_native_payload_bridge(){let snapshot=fixture();let payload=store::os_io::IoPayload::Binary(<SemioGraphSnapshot as store::ArtifactPack>::encode_pack(&snapshot));let codec=store::ArtifactCodec::bare::<SemioGraphSnapshot,crate::standards::v1::subsets::graph::schema::mutations::SemioGraphMutation>("s.stdio.semio.graph");let provider=codec.snapshot_sqlite.expect("owner must publish typed SQLite capability");assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<SemioGraphSnapshot>()));let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"graph".into()};let db=(provider.export)("s.stdio.semio.graph",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let bytes=export_sqlite_database(&db,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let db=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=(provider.import)("s.stdio.semio.graph",&dialect,db,SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(actual,payload);}

#[test]
fn sqlite_snapshot_semio_graph_owned_numeric_bits_independent_sqlite(){use std::io::Write;use std::process::{Command,Stdio};let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();for(index,bits)in f["float64Bits"].as_array().unwrap().iter().enumerate(){let bits=u64::from_str_radix(bits.as_str().unwrap(),16).unwrap();let bits32=u32::from_str_radix(f["float32Bits"][index].as_str().unwrap(),16).unwrap();let v=f64::from_bits(bits);let _v32=f32::from_bits(bits32);let mut s=fixture();s.nodes[0].position.x=v;let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');await Bun.write(Bun.stdout,d.serialize());d.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let r=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!((r.nodes[0].position.x).to_bits(),bits);assert_eq!(<SemioGraphSnapshot as store::ArtifactPack>::encode_pack(&r),<SemioGraphSnapshot as store::ArtifactPack>::encode_pack(&s));}}

#[test]
fn sqlite_snapshot_semio_graph_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|store::os_io::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_graph_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_graph_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"graph".into()};
    let provider=<SemioGraphSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<SemioGraphSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<SemioGraphSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert_eq!(actual,expected);
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioGraphSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}
